app.post("/dispatches", (request, response, next) => {
  const assignedAt = new Date().toISOString();
  const body = request.body === undefined ? {} : request.body;
  const validationErrors = validateDispatchRequest(body);

  respondAfterLatency(() => {
    if (validationErrors.length > 0) {
      response.status(400).json({
        error: {
          code: "VALIDATION_ERROR",
          message: "Dispatch request is invalid",
          details: validationErrors,
        },
      });
      return;
    }

    const dispatch = createDispatch(body, assignedAt);
    dispatches.set(dispatch.dispatchId, dispatch);

    response
      .location(`/dispatches/${dispatch.dispatchId}`)
      .status(201)
      .json(dispatch);
  }, next);
});

app.get("/dispatches/:dispatchId", (request, response, next) => {
  respondAfterLatency(() => {
    const dispatch = dispatches.get(request.params.dispatchId);

    if (dispatch === undefined) {
      response.status(404).json({
        error: {
          code: "DISPATCH_NOT_FOUND",
          message: "No dispatch was found for the supplied dispatch ID",
        },
      });
      return;
    }

    response.status(200).json(dispatch);
  }, next);
});

app.patch("/dispatches/:dispatchId/status", (request, response, next) => {
  const body = request.body === undefined ? {} : request.body;
  const nextStatus = body.status;

  respondAfterLatency(() => {
    const dispatch = dispatches.get(request.params.dispatchId);

    if (dispatch === undefined) {
      response.status(404).json({
        error: {
          code: "DISPATCH_NOT_FOUND",
          message: "No dispatch was found for the supplied dispatch ID",
        },
      });
      return;
    }

    const currentIndex = statusOrder.indexOf(dispatch.status);
    const nextIndex = statusOrder.indexOf(nextStatus);

    if (nextIndex !== currentIndex + 1) {
      response.status(400).json({
        error: {
          code: "VALIDATION_ERROR",
          message: `status can only advance from "${dispatch.status}" to "${
            statusOrder[currentIndex + 1] ?? "(no further status)"
          }"`,
        },
      });
      return;
    }

    dispatch.status = nextStatus;
    dispatch.updatedAt = new Date().toISOString();

    response.status(200).json(dispatch);
  }, next);
});

app.use((_request, response) => {

  if (latitudeResult.error !== undefined) {
    validationErrors.push(latitudeResult.error);
  }

  if (longitudeResult.error !== undefined) {
    validationErrors.push(longitudeResult.error);
  }

  if (!emergencyTypes.has(emergencyType)) {
    validationErrors.push("emergencyType is not a supported value");
  }

  if (validationErrors.length > 0) {
    response.status(400).json({
      error: {
        code: "VALIDATION_ERROR",
        message: "Route request is invalid",
        details: validationErrors,
      },
    });
    return;
  }

  const cacheKey = buildRouteCacheKey(
    latitudeResult.value,
    longitudeResult.value,
    emergencyType,
  );

  const buildRouteResult = () => {
    const { region, distanceMeters } = findNearestRegion(
      latitudeResult.value,
      longitudeResult.value,
    );

    if (region === null || distanceMeters > maximumRoutingDistanceMeters) {
      return { notFound: true };
    }

    return {
      notFound: false,
      body: {
        regionId: region.regionId,
        regionName: region.regionName,
        location: {
          latitude: latitudeResult.value,
          longitude: longitudeResult.value,
        },
        emergencyType,
        responseGroup: selectResponseGroup(region, emergencyType),
        matchedBy: "coordinates",
        distanceMeters: Math.round(distanceMeters),
      },
    };
  };

  const logCacheEvent = (cacheStatus) => {
    console.log(
      JSON.stringify({
        level: "info",
        message: "Route cache lookup",
        servedBy: replicaId,
        cacheKey,
        cacheStatus,
      }),
    );
  };

  // AI: Sprint 3 cache hits skip respondAfterLatency entirely so the endpoint demonstrably
  // answers faster on a repeated location than it does on first access.
  // AI: Austin's review fix — a Redis outage previously bubbled up to `next`
  // and returned a 500/504, even though the replica can still compute the
  // route itself. A failed cache read is now treated as a cache miss instead.
  let cachedValue = null;

  try {
    cachedValue = await redisClient.get(cacheKey);
  } catch (error) {
    console.error(
      JSON.stringify({
        level: "error",
        message: "Redis cache read failed; falling back to direct route calculation",
        error: error instanceof Error ? error.message : String(error),
      }),
    );
  }

  if (cachedValue !== null) {
    logCacheEvent("HIT");
    const cachedBody = JSON.parse(cachedValue);
    response.status(200).json({
      servedBy: replicaId,
      ...cachedBody,
      routedAt: new Date().toISOString(),
      cache: "HIT",
    });
    return;
  }

  logCacheEvent("MISS");

  respondAfterLatency(() => {
    const result = buildRouteResult();

    if (result.notFound) {
      response.status(404).json({
        error: {
          code: "REGION_NOT_FOUND",
          message: "No region could be matched for the supplied coordinates",
        },
      });
      return;
    }

    redisClient
      .set(cacheKey, JSON.stringify(result.body), {
        EX: routeCacheTtlSeconds,
      })
      .catch((error) => {
        console.error(
          JSON.stringify({
            level: "error",
            message: "Failed to store route result in cache",
            error: error instanceof Error ? error.message : String(error),
          }),
        );
      });

    response.status(200).json({
      servedBy: replicaId,
      ...result.body,
      routedAt: new Date().toISOString(),
      cache: "MISS",
    });
  }, next);
});

